package com.ecommerce.config;
import org.springframework.context.annotation.Configuration; import org.springframework.scheduling.annotation.EnableAsync; import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor; import org.springframework.context.annotation.Bean; import java.util.concurrent.Executor;
@Configuration @EnableAsync public class AsyncConfig { @Bean(name="reportExecutor") public Executor reportExecutor(){ThreadPoolTaskExecutor e=new ThreadPoolTaskExecutor();e.setCorePoolSize(2);e.setMaxPoolSize(4);e.setQueueCapacity(50);e.setThreadNamePrefix("report-");e.initialize();return e;} }
